def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'C'
    my_last, opp_last = history[-1]
    opp_defects = sum(1 for a, b in history if b == 'D')
    my_defects = sum(1 for a, b in history if a == 'D')
    last_opp_defects = 0
    for i in range(len(history) - 1, -1, -1):
        if history[i][1] == 'D':
            last_opp_defects = len(history) - i
            break
    if n == 1:
        if opp_last == 'D':
            return 'D'
        return 'C'
    if n < 5:
        if opp_defects >= 1:
            return 'D'
        return 'C'
    if opp_defects == 0:
        return 'C'
    recent = history[-5:]
    recent_opp_defects = sum(1 for a, b in recent if b == 'D')
    recent_my_defects = sum(1 for a, b in recent if a == 'D')
    if recent_opp_defects >= 3:
        return 'D'
    if recent_opp_defects == 0:
        if recent_my_defects > 0:
            return 'C'
        return 'C'
    if recent_opp_defects == 1:
        if recent_my_defects >= 2:
            return 'D'
        return 'C'
    if opp_defects * 3 > n:
        return 'D'
    if opp_last == 'D' and my_last == 'C':
        return 'D'
    if opp_last == 'D' and my_last == 'D':
        if rng.random() < 0.3:
            return 'C'
        return 'D'
    if last_opp_defects > 0 and last_opp_defects <= 3 and opp_defects * 4 < n:
        return 'C'
    endgame = 100 - n
    if endgame <= 2:
        if opp_defects > 0:
            return 'D'
        return 'C'
    if opp_defects * 2 > n:
        return 'D'
    return 'C'
